from pathlib import Path
p=Path('online-preview/app.js');s=p.read_text(encoding='utf-8')
s=s.replace("'<span class=\"spinner\"></span><p id=\"analysis-progress\">${esc(analysisProgress||'Đang kiểm tra các nước hợp lệ…')}</p>'", "`<span class=\"spinner\"></span><p id=\"analysis-progress\">${esc(analysisProgress||'Đang kiểm tra các nước hợp lệ…')}</p>`")
start=s.index('function profile(');end=s.index('function about(',start)
s=s[:start]+r'''
function profile(){const records=completed(),stats=CC.evidence(state.records);return `${heading('Tiến độ của bạn','Chỉ ghi nhận hoạt động thực tế trên trình duyệt này.')}<div class="stat-grid"><div class="stat"><b>${stats.count}</b><span>lượt luyện đã kết thúc</span></div><div class="stat"><b>${dueRecords().length}</b><span>hình đến hạn ôn</span></div><div class="stat"><b>${stats.firstEligible?Math.round(stats.firstCorrect/stats.firstCount*100)+'%':'—'}</b><span>${stats.firstEligible?`nước đầu phù hợp mẫu, không hỗ trợ · ${stats.firstCorrect}/${stats.firstCount} bài`:'Chưa đủ dữ liệu · cần 6 bài khác nhau để hiện tỷ lệ'}</span></div></div><p class="notice">Trình độ tự chọn: ${prefs.level==='new'?'Chưa biết chơi':prefs.level==='beginner'?'Mới biết luật':'Đã biết chơi'}. Đây không phải kết quả đánh giá đầu vào hoặc xếp hạng thi đấu.</p><div class="grid-2"><section class="panel"><h3>Bằng chứng theo kỹ năng</h3>${Object.entries(SKILLS).map(([k,n])=>{const e=CC.evidence(state.records,k);return `<div class="skill-row"><h4>${n}</h4><p>${e.eligible?`${e.count} lượt · ${e.independent} lượt chọn nước phù hợp không hỗ trợ · ${e.assisted} lượt có hỗ trợ`:`Chưa đủ dữ liệu (${e.count}/6 lượt). Chưa hiện biểu đồ hoặc điểm kỹ năng.`}</p>${e.eligible?`<progress max="${e.count}" value="${e.independent}" aria-label="Lượt chọn nước phù hợp không hỗ trợ"></progress>`:''}</div>`;}).join('')}<p class="subtle">Kết quả nước đi không chứng minh chất lượng lý giải hoặc mức thành thạo.</p><a class="secondary" href="#review">Đến lịch ôn →</a></section><section class="panel"><h3>Góc cá nhân</h3><form id="profile-form"><label class="field"><span>Tên hiển thị</span><input type="text" name="name" maxlength="40" value="${esc(state.profile.name)}" placeholder="Bạn muốn được gọi là gì?"></label><button class="secondary" type="submit">Lưu tên</button></form><p class="subtle separation">Hồ sơ trên trình duyệt, chưa có tài khoản đồng bộ. Đổi thiết bị không tự mang theo tiến độ.</p><a class="secondary" href="#settings">Giao diện và dữ liệu →</a></section></div><section class="panel separation"><h3>Những lần tự nhìn lại</h3>${state.summaries.length?state.summaries.slice(-5).reverse().map(item=>`<div class="explanation-section"><h4>${date(item.at)}</h4><p>${esc(item.note||'Đã lưu tự đánh giá.')} (${item.checks.length} mục)</p></div>`).join(''):'<p>Chưa có tự đánh giá. Sau phiên học, bạn có thể ghi một điều muốn nhớ.</p>'}</section>`;}
''' +s[end:]
s=s.replace('File UI/UX + Luật và các câu trả lời bổ sung sẽ tiếp tục định hướng bản Vercel.','Đã cập nhật các lựa chọn trong UI/UX + Luật và UX35. Các mục chưa đủ điều kiện triển khai được ghi riêng trong bộ câu hỏi V5.')
s=s.replace('Bộ luật chưa phân xử chiếu dai/đuổi dai giải đấu.','Bộ luật chỉ xử lý được một số chuỗi lặp và chiếu liên tục rõ ràng; đuổi dai, chiếu đuổi hỗn hợp và phán quyết giải đấu vẫn cần kiểm chứng.')
start=s.index('function render(')
s=s[:start]+r'''
function applyPreferences(){document.documentElement.dataset.theme=prefs.theme;document.documentElement.dataset.font=prefs.font;document.body.classList.toggle('sidebar-collapsed',prefs.sidebar);$('sidebar-toggle')?.setAttribute('aria-expanded',String(!prefs.sidebar));$('sound-toggle')?.setAttribute('aria-pressed',String(prefs.sound));if($('sound-toggle'))$('sound-toggle').textContent=prefs.sound?'♪ Âm thanh bật':'♪ Âm thanh tắt';try{localStorage.setItem(PREF_KEY,JSON.stringify(prefs));}catch{toast('Không lưu được tùy chọn trên thiết bị.');}}
function playSound(kind){if(!prefs.sound)return;try{audioContext=audioContext||new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();const now=audioContext.currentTime,o=audioContext.createOscillator(),gain=audioContext.createGain();o.type='sine';o.frequency.setValueAtTime(({move:420,capture:220,check:660,success:880,error:160})[kind]||420,now);gain.gain.setValueAtTime(0.001,now);gain.gain.exponentialRampToValueAtTime(.06,now+.02);gain.gain.exponentialRampToValueAtTime(.001,now+.2);o.connect(gain);gain.connect(audioContext.destination);o.start();o.stop(now+.22);}catch{/* Sound is optional; gameplay remains available. */}}
function settings(){const select=(key,label,options)=>`<label class="field"><span>${label}</span><select name="${key}">${options.map(([v,t])=>`<option value="${v}" ${prefs[key]===v?'selected':''}>${t}</option>`).join('')}</select></label>`;return `${heading('Cài đặt','Chọn cách hiển thị thoải mái cho bạn.')}<div class="settings-grid grid-2"><section class="panel"><h3>Giao diện và bàn cờ</h3><form id="settings-form">${select('theme','Chủ đề',[['warm','Sáng ấm'],['cool','Trắng lạnh'],['dark','Tối']])}${select('pieces','Tên quân',[['han','Chữ Hán'],['vi','Tiếng Việt']])}${select('font','Cỡ chữ',[['normal','Dễ đọc'],['large','Lớn hơn']])}${select('level','Mức tự chọn',[['new','Chưa biết chơi'],['beginner','Mới biết luật'],['intermediate','Đã biết chơi']])}${select('tone','Giọng hướng dẫn',[['neutral','Trung tính'],['friendly','Bạn học cùng']])}<label class="check-line"><input type="checkbox" name="sound" ${prefs.sound?'checked':''}> Bật âm thanh nhẹ</label><button class="primary" type="submit">Lưu tùy chọn</button></form><p class="subtle separation">Âm thanh được tổng hợp trên thiết bị. Không sử dụng âm thanh từ ứng dụng khác.</p></section><section class="panel"><h3>Dữ liệu và quyền riêng tư</h3><p>Phiên học được lưu trên trình duyệt này. Chưa có tài khoản, lưu máy chủ hoặc đồng bộ thiết bị.</p><p>Không gửi ván hoặc câu trả lời để huấn luyện. Bản xuất không chứa đáp án ẩn của bài tập.</p><div class="button-row">${btn('Xuất dữ liệu cá nhân','export','','secondary')}${btn('Xóa lịch sử học và lịch ôn','delete-learning','','danger')}${btn('Xóa toàn bộ dữ liệu','delete','','danger')}</div><p class="subtle separation">File xuất là bản sao để đọc; chưa có nhập phục hồi tự động. Xóa dữ liệu không thể hoàn tác.</p><a href="#profile" class="secondary">Quay về hồ sơ →</a></section></div>`;}
function howto(){return `${heading('Bắt đầu với Cờ Chill','Một ván cờ, một điều hiểu rõ hơn.')}<div class="grid-2"><section class="panel"><h2>Bạn đang ở đâu?</h2><p>Chọn để điều chỉnh mức gợi mở. Đây là thông tin tự khai, chưa phải bài kiểm tra xếp hạng.</p><div class="button-row">${btn('Tôi chưa biết chơi','onboard','new','secondary')}${btn('Tôi mới biết luật','onboard','beginner','secondary')}${btn('Tôi đã biết chơi','onboard','intermediate','secondary')}</div><p class="subtle separation">Không cần nhập tuổi hoặc thông tin liên hệ để thử. Bản này lưu trên cùng trình duyệt.</p></section><section class="panel"><h3>Cách thao tác</h3><ol><li>Bấm một quân, rồi bấm ô muốn đi. Bấm lại quân đó để hủy chọn.</li><li>Sau ván, chọn một vị trí cần xem lại.</li><li>Viết suy nghĩ và chọn nước trước khi xem hướng dẫn.</li><li>Thử thêm một bài, rồi xem lịch ôn và ghi điều đã học.</li></ol><p>Nếu chưa tìm ra, dùng “Tôi chưa biết” để nhận câu hỏi quan sát nhỏ hơn.</p><div class="button-row">${btn('Thử một bài mẫu →','start',FIXTURES[0].id)}<a class="secondary" href="#play">Bỏ qua hướng dẫn · chơi cờ</a></div></section></div><p class="notice separation">Bài mẫu tự dựng, không phải ván của người dùng thật. Video hướng dẫn sẽ bổ sung sau; bản này có hướng dẫn chữ và bàn cờ tương tác.</p>`;}
function learningPath(){const stages=[['01','Nắm luật đi quân','Nhận ra đường đi và những điều kiện bị cản.','rules','Xem luật'],['02','Quan sát một hình cờ','Tự nêu ý trước khi xem hướng dẫn.','lessons','Chọn bài'],['03','Chơi và nhìn lại','Tìm một quyết định đáng học từ ván của bạn.','play','Chơi cờ'],['04','Vận dụng và ôn lại','Làm thêm bài rồi trở lại đúng lịch đã hẹn.','review','Mở lịch ôn']];return `${heading('Hành trình học','Bốn bước có thể quay lại bất cứ lúc nào.')}<div class="learning-path">${stages.map(([n,t,d,url,cta])=>`<article class="path-node panel"><span class="mini-icon">${n}</span><div><h2>${t}</h2><p>${d}</p><a class="secondary" href="#${url}">${cta} →</a></div></article>`).join('')}</div><p class="notice separation">Lộ trình gợi ý, chưa phải giáo trình phân cấp hoặc bài đánh giá đầu vào đã được kiểm chứng. Không khóa bài theo điểm kinh nghiệm giả.</p>`;}
function rulesPage(){const rules=[['Tướng','Đi thẳng hoặc ngang một ô trong cung. Hai Tướng không được nhìn thẳng nhau trên cùng cột khi không có quân chắn.'],['Sĩ','Đi chéo một ô và luôn ở trong cung.'],['Tượng','Đi chéo hai ô, không qua sông. Ô giữa đường chéo là mắt Tượng; có quân ở đó thì không đi được.'],['Mã','Đi một ô thẳng rồi một ô chéo ra ngoài. Ô thẳng đầu tiên là chân Mã; bị chặn thì không đi được hướng đó.'],['Xe','Đi thẳng hoặc ngang qua các ô trống; không nhảy qua quân.'],['Pháo','Khi không ăn quân, đi như Xe. Khi ăn quân, phải có đúng một quân nằm giữa Pháo và mục tiêu.'],['Tốt','Mỗi nước tiến một ô. Qua sông được đi ngang một ô; không bao giờ đi lùi.']];return `${heading('Luật đi quân','Tọa độ trên bàn không thay đổi khi lật góc nhìn.','howto')}<div class="grid-2">${rules.map(([n,t])=>`<section class="panel"><h3>${n}</h3><p>${t}</p></section>`).join('')}<section class="panel"><h3>An toàn Tướng và hết ván</h3><p>Không được đi nước khiến Tướng mình bị chiếu. Chiếu hết hoặc hết nước hợp lệ đều là thua. Hết giờ và xin thua được ghi riêng; thỏa thuận hòa cần hai người cùng đồng ý.</p></section></div><section class="panel separation"><h3>Lặp thế và phán quyết</h3><p>Đối chiếu WXF Rules 2018. Bản thử xử lý chuỗi chiếu một bên lặp rõ ràng; các chuỗi đuổi quân hoặc vừa chiếu vừa đuổi cần kiểm chứng. Chạm mốc lặp hoặc 100 nửa nước không ăn quân có thể dừng để xác minh; không tự suy thành hòa khi còn ngoại lệ.</p><p>Không dùng bản này làm trọng tài giải đấu. Các tình huống chưa rõ sẽ được bổ sung bằng case và nguồn luật cụ thể.</p><a class="secondary" href="https://www.wxf-xiangqi.org/images/wxf-rules/2018_World_Xiangqi_Rules_English.pdf" target="_blank" rel="noopener">Nguồn WXF</a></section><div class="button-row">${state.session?btn('Trở lại bài đang học','resume'):btn('Thực hành một hình','start',FIXTURES[0].id)}<a class="quiet" href="#howto">Quay lại cách học</a></div>`;}
function render(){const [page,id]=route();let content;try{if(activeGame()&&['learn','opening','moments','replay','lessons','rules'].includes(page)){content=empty('Ván đang diễn ra','Hãy kết thúc ván trước khi mở hướng dẫn hoặc xem lại.','game/'+activeGame().id,'Tiếp tục ván');}else switch(page){case'play':content=playSetup();break;case'lessons':content=lessons();break;case'learn':content=learn();break;case'opening':content=opening(Number(id));break;case'game':content=gameView(state.games.find(g=>g.id===id));break;case'moments':content=moments(state.games.find(g=>g.id===id));break;case'replay':content=replay(state.games.find(g=>g.id===id));break;case'mistakes':content=mistakes();break;case'review':content=reviews();break;case'summary':content=summary();break;case'profile':content=profile();break;case'about':content=about();break;case'settings':content=settings();break;case'howto':content=howto();break;case'path':content=learningPath();break;case'rules':content=rulesPage();break;default:content=home();}}catch(e){content=empty('Không mở được dữ liệu này','Dữ liệu cũ vẫn được giữ. Bạn có thể xuất bản sao trong hồ sơ.','settings','Mở dữ liệu');console.error(e);} $('main').innerHTML=content;$('avatar').textContent=(state.profile.name||'C').slice(0,1).toUpperCase();document.querySelectorAll('.desktop-nav a,.mobile-nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+page));document.title=(document.querySelector('#main h1')?.textContent||'Trang chủ')+' · Cờ Chill';applyPreferences();}
function invalidMove(g,pos,move){const message=CC.illegalMoveReason(pos,move);if(g){g.invalidMoves=(g.invalidMoves||[]).concat({at:Date.now(),move,reason:message}).slice(-100);save();}const box=$('game-feedback')||$('move-feedback');if(box)box.textContent=message;playSound('error');toast(message);}
function selectSquare(sq){const [page,id]=route();if(page==='game'){const g=state.games.find(x=>x.id===id);if(!g||g.status.over||busy)return;const pos=XQ.Position.fromFen(g.fen);if(g.mode==='bot'&&pos.turn!==g.player)return;const piece=pos.board[XQ.index(sq)];if(piece!=='.'&&XQ.side(piece)===pos.turn){selected=selected===sq?null:sq;return render();}if(!selected)return toast('Chọn quân của bên đến lượt trước.');const move=selected+sq;if(!pos.legalMoves().includes(move))return invalidMove(g,pos,move);return moveGame(g,move);}
 if(page!=='learn'||!state.session)return;const session=state.session,p=currentPuzzle();if(!['reflect','retry'].includes(session.stage))return;const pos=XQ.Position.fromFen(p.fen),piece=pos.board[XQ.index(sq)];if(piece!=='.'&&XQ.side(piece)===pos.turn){selected=selected===sq?null:sq;session.selected=selected;save();return render();}if(!selected)return toast('Chọn quân của bên đến lượt trước.');const move=selected+sq;if(!pos.legalMoves().includes(move))return invalidMove(null,pos,move);selected=null;session.selected=null;if(session.stage==='retry'){session.retryCount=(session.retryCount||0)+1;if(accepted(p,move)){toast('Bạn đã đi lại được phương án. Lần đầu và lần luyện lại được ghi riêng.');playSound('success');session.stage='explain';}else if(session.retryCount>=3){session.stage='explain';toast('Đã thử ba lượt. Hãy đối chiếu ý tưởng và đưa hình này vào ôn tập.');}else{toast('Nước hợp lệ nhưng chưa khớp mục tiêu mẫu. Kiểm tra phản ứng của đối phương.');playSound('error');}}else session.candidate=move;save();render();}
function download(name,contents,type='application/json'){const url=URL.createObjectURL(new Blob([contents],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
document.addEventListener('click',e=>{const square=e.target.closest('[data-square]');if(square)return selectSquare(square.dataset.square);const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,v=el.dataset.value;try{switch(a){
 case'toggle-sidebar':prefs.sidebar=!prefs.sidebar;applyPreferences();break;
 case'toggle-sound':prefs.sound=!prefs.sound;applyPreferences();playSound('move');break;
 case'toggle-pieces':prefs.pieces=prefs.pieces==='han'?'vi':'han';render();break;
 case'flip-board':boardFlipped=!boardFlipped;render();break;
 case'onboard':prefs.level=v;applyPreferences();go(v==='new'?'rules':'lessons');break;
 case'start':beginPuzzle(findPuzzle(v),{source:v.startsWith('g')?'game':'lesson'});break;
 case'start-review':beginPuzzle(findPuzzle(v),{source:'review'});break;
 case'resume':selected=state.session?.selected||null;showVariation=false;go('learn');break;
 case'pause':if(!confirm('Lưu chỗ đang học và về trang chủ? Bạn có thể tiếp tục sau.'))break;save();go('home');toast('Đã giữ chỗ và câu trả lời trên trình duyệt này.');break;
 case'unknown':{const session=state.session;if(!session||session.stage!=='reflect')break;session.assisted=true;session.helpLevel=Math.min(3,(session.helpLevel||0)+1);if(!session.helpReadyAt)session.helpReadyAt=Date.now()+10000;save();render();break;}
 case'guided-reveal':{const session=state.session;if(!session||session.stage!=='reflect'||!session.helpLevel||Date.now()<session.helpReadyAt)break;session.unknown=true;session=undefined;break;}
 case'retry':if((state.session.retryCount||0)>=3){toast('Bạn đã dùng ba lượt thử lại. Hãy kết thúc lượt học để hẹn ôn.');break;}state.session.stage='retry';showVariation=false;selected=null;save();render();break;
 case'explain':state.session.stage='explain';save();render();break;
 case'variation':showVariation=!showVariation;render();break;
 case'marks':showMarks=!showMarks;render();break;
 case'finish':playSound('success');finish();break;
 case'next-related':nextRelated();break;
 case'related-start':beginPuzzle(findPuzzle(state.session.pendingPuzzleId),{related:true,source:'related',force:true});break;
 case'summary':go('summary');break;
 case'phase':lessonPhase=v;render();break;
 case'opening':replayIndex=0;go('opening/'+v);break;
 case'opening-before':replayIndex=0;render();break;
 case'opening-after':replayIndex=1;render();break;
 case'mode':mode=v;render();break;
 case'analyze':analyzeGame(state.games.find(g=>g.id===v));break;
 case'resign':case'draw':{const g=state.games.find(x=>x.id===v);if(!g||g.status.over)break;if(a==='draw'&&g.mode!=='local')break;if(!confirm(a==='resign'?'Xin thua và kết thúc ván này?':'Cả hai người cùng đồng ý hòa ván này?'))break;g.status={over:true,winner:a==='resign'?XQ.other(g.mode==='bot'?g.player:XQ.Position.fromFen(g.fen).turn):null,reason:a==='resign'?'Xin thua':'Hai bên thỏa thuận hòa'};save();render();break;}
 case'rematch':{const g=state.games.find(x=>x.id===v);mode=g.mode==='local'?'local':'bot';newGame({color:'random',depth:g.depth,seconds:g.clock?.enabled?600:0,increment:g.clock?.enabled?5:0});break;}
 case'replay-prev':replayIndex--;render();break;
 case'replay-next':replayIndex++;render();break;
 case'replay-jump':replayIndex=Number(v);render();break;
 case'library-filter':libraryFilter=v;libraryPage=0;render();break;
 case'library-prev':libraryPage=Math.max(0,libraryPage-1);render();break;
 case'library-next':libraryPage++;render();break;
 case'favorite':{const g=state.games.find(x=>x.id===v);g.favorite=!g.favorite;save();render();break;}
 case'export-game':{const g=state.games.find(x=>x.id===v);const text=CC.pairMoveHistory(g.initialFen,g.moves).map(r=>`${r.number}. ${r.red?.notation||'...'} ${r.black?.notation||''}`).join('\n');download('co-chill-bien-ban.txt',`FEN: ${g.initialFen}\n\n${text}`,'text/plain');break;}
 case'delete-game':{const g=state.games.find(x=>x.id===v);if(!g?.status.over)break;if(!confirm('Xóa ván này và các lượt luyện/lịch ôn trực tiếp từ ván này trên trình duyệt? Bài trong thư viện và ghi chú tự đánh giá khác được giữ.'))break;state.games=state.games.filter(x=>x.id!==v);for(const id of Object.keys(state.records))if(id.startsWith(v+'-p'))delete state.records[id];if(state.session?.puzzleId.startsWith(v+'-p'))state.session=null;save();go('mistakes');break;}
 case'export':download('co-chill-du-lieu-ca-nhan.json',JSON.stringify(CC.safeExport(state),null,2));toast('Đã tạo bản xuất không kèm đáp án ẩn.');break;
 case'delete-learning':if(confirm('Xóa câu trả lời, lượt luyện, lịch ôn và tự đánh giá trên trình duyệt này? Các ván cờ được giữ.')){state.records={};state.session=null;state.summaries=[];save();render();toast('Đã xóa dữ liệu học.');}break;
 case'delete':if(confirm('Xóa toàn bộ ván, câu trả lời, lịch ôn, hồ sơ và cài đặt trên trình duyệt này? Hãy xuất dữ liệu trước nếu cần.')){localStorage.removeItem(KEY);localStorage.removeItem(PREF_KEY);state=CC.fresh();prefs=CC.preferences();selected=null;save();render();toast('Đã xóa toàn bộ dữ liệu của bản này.');}break;
 }}catch(err){toast(err.message||'Chưa thực hiện được. Dữ liệu được giữ lại.');}});
document.addEventListener('input',e=>{if(e.target.dataset.answer!==undefined&&state.session){state.session.answers[Number(e.target.dataset.answer)]=e.target.value;save();if($('draft-status'))$('draft-status').textContent=storageOK?'Đã lưu trên trình duyệt này':'Chưa lưu được · hãy sao chép câu trả lời';}if(e.target.closest('#summary-form')&&state.session){const form=e.target.closest('form');state.session.summaryNote=form.elements.note.value;state.session.summaryChecks=[...form.querySelectorAll('[name=check]:checked')].map(x=>x.value);save();}});
document.addEventListener('change',async e=>{if(e.target.id!=='notation-file')return;const file=e.target.files?.[0];if(!file)return;if(file.size>50000)return toast('File quá lớn. Bản thử nhận tối đa 50 KB văn bản.');const text=await file.text(),fen=text.match(/^FEN:\s*(.+)$/m);if(fen)e.target.form.elements.fen.value=fen[1].trim();e.target.form.elements.moves.value=text.replace(/^FEN:.*$/m,'').trim();});
document.addEventListener('submit',e=>{if(!['reflection-form','new-game-form','import-form','summary-form','profile-form','settings-form'].includes(e.target.id))return;e.preventDefault();const data=new FormData(e.target);try{switch(e.target.id){
 case'reflection-form':{const session=state.session,p=currentPuzzle(),check=CC.reflectionCheck(session,p);if(!check.ready){const message=check.missing.length?'Hãy viết suy nghĩ ở cả ba câu. Có thể dùng gợi ý nếu bạn chưa biết.':'Chọn một nước trên bàn trước khi gửi.';$('learn-feedback').textContent=message;document.querySelector(check.missing.length?`[data-answer="${check.missing[0]}"]`:'[data-square]')?.focus();return;}if(!session.firstAnswers){session.firstAnswers=session.answers.slice();session.firstCandidate=session.candidate;}session.submissionCount=check.attempts;session.assisted=check.assisted;if(check.reveal){state.session=CC.reveal(session);selected=null;showVariation=false;}else{session.helpLevel=Math.max(1,session.helpLevel||0);session.coachFeedback='Nước này hợp lệ nhưng chưa khớp mục tiêu mẫu. Bạn thử kiểm tra Tướng, đường quân và phản ứng đối thủ một lần nữa. Câu tự luận chưa được tự động chấm.';playSound('error');}save();render();break;}
 case'new-game-form':{const [seconds,increment]=String(data.get('time')).split('+').map(Number);newGame({color:data.get('color'),seconds,increment,depth:Number(data.get('depth')||1)});break;}
 case'import-form':{if(activeGame())return toast('Kết thúc ván đang chơi trước khi nhập để học.');const fen=String(data.get('fen')).trim()||XQ.START_FEN,parsed=CC.parseGameNotation(fen,String(data.get('moves')||''),200);newGame({fen,moves:parsed.moves,imported:true,color:String(data.get('reviewSide'))});break;}
 case'summary-form':state=CC.summarizeSession(state,{checks:data.getAll('check'),note:data.get('note')});state.session.stage='summary';save();go('home');toast('Đã lưu tự đánh giá. Lịch ôn của từng hình được giữ riêng.');break;
 case'profile-form':state.profile.name=String(data.get('name')).trim().slice(0,40);save();render();toast('Đã lưu tên trên thiết bị.');break;
 case'settings-form':prefs=CC.preferences({...Object.fromEntries(data.entries()),sound:data.has('sound'),sidebar:prefs.sidebar});render();toast('Đã lưu giao diện trên trình duyệt này.');break;
 }}catch(err){const box=$('import-feedback')||$('learn-feedback');if(box)box.textContent=err.message;else toast(err.message);}});
document.addEventListener('keydown',e=>{const button=e.target.closest('[data-square]');if(!button)return;if(e.key==='Escape'){selected=null;render();return;}if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const i=XQ.index(button.dataset.square),step=({ArrowLeft:-1,ArrowRight:1,ArrowUp:-9,ArrowDown:9}[e.key])*(boardFlipped?-1:1),j=i+step;if(j>=0&&j<90&&(Math.abs(step)===9||Math.floor(i/9)===Math.floor(j/9)))document.querySelector(`[data-square="${XQ.square(j)}"]`)?.focus();});
let internalNavigation=false,restoringNavigation=false;
function guardedNavigation(){if(restoringNavigation){restoringNavigation=false;return;}const before=previousRoute.slice(1).split('/')[0],after=route()[0],leaving=before!==after&&((before==='game'&&activeGame())||(before==='learn'&&state.session?.stage==='reflect'));if(leaving&&!internalNavigation&&!confirm(before==='game'?'Rời trang ván cờ? Ván được giữ, nhưng đồng hồ vẫn chạy.':'Rời bài đang suy nghĩ? Câu trả lời được lưu để tiếp tục sau.')){restoringNavigation=true;location.hash=previousRoute;return;}internalNavigation=false;previousRoute=location.hash;selected=null;render();window.scrollTo(0,0);$('main').focus({preventScroll:true});const [page,id]=route();if(page==='game')maybeBot(state.games.find(g=>g.id===id));}
window.addEventListener('hashchange',guardedNavigation);
window.addEventListener('beforeunload',e=>{save();if(activeGame()||route()[0]==='learn'&&state.session?.stage==='reflect'){e.preventDefault();e.returnValue='';}});
window.addEventListener('storage',e=>{if(e.key!==KEY)return;try{state=CC.sanitize(JSON.parse(e.newValue));selected=null;render();toast('Đã nhận thay đổi từ tab khác.');}catch{toast('Không đọc được thay đổi từ tab khác.');}});
setInterval(()=>{const g=activeGame();if(g){if(tickGame(g)){if(route()[0]==='game')render();}else for(const color of ['w','b'])if($('clock-'+color))$('clock-'+color).textContent=clockText(g,color);}const help=$('guided-reveal');if(help&&state.session){const wait=Math.max(0,Math.ceil(((state.session.helpReadyAt||0)-Date.now())/1000));help.disabled=wait>0;help.textContent=wait?`Quan sát thêm ${wait} giây`:'Vẫn chưa tìm ra · xem hướng dẫn';}},300);
save();render();const initial=activeGame();if(initial){tickGame(initial);maybeBot(initial);}
'''
# Reuse the shared reveal gate only after the explicit help interval.
s=s.replace("session.unknown=true;session=undefined;break;", "session.unknown=true;state.session=CC.reveal(session);selected=null;showVariation=false;save();render();break;")
s=s.replace("function go(route){if(location.hash==='#'+route)render();else location.hash=route;}","function go(route){if(location.hash==='#'+route)render();else{internalNavigation=true;location.hash=route;}}")
p.write_text(s,encoding='utf-8')
